/**
 * Grounding module — injects real-world enrichment data into the engines.
 *
 * The enrichment.json snapshot (generated by `npm run enrich`) is a static,
 * offline, versioned file. Loading it is deterministic: the same snapshot file
 * always produces the same grounded engine parameters, so replay/observables
 * remain bit-identical for a given snapshot.
 *
 * This module parses the snapshot into the exact parameter shapes each engine
 * subsystem (chemistry, ecology) consumes, plus a provenance record used by the
 * research ladder and browser to show WHERE the data came from.
 */

import { readFileSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import {
  EnrichmentSnapshot,
  type EnrichmentSnapshot as SnapType,
  type EngineStoichiometry,
} from '@fractal-life/shared';

const __dirname = dirname(fileURLToPath(import.meta.url));
/** Default snapshot path (checked in at repo, deterministic). */
export const ENRICHMENT_PATH = resolve(__dirname, '..', '..', 'data', 'enrichment.json');

export interface ChemistryGrounding {
  /** stoichiometric element ratios [C,H,O,N,P,S,Fe,K] for plant food digestion */
  plant: number[];
  /** same, for meat digestion */
  meat: number[];
  aminoAcid: number[];
  fattyAcid: number[];
  sugar: number[];
  glucose: number[];
  /** real molecular formulas per molecule index (role -> formula) for provenance */
  molecularFormulas: Record<number, string>;
  mole_names: string[];
}

export interface EcologyGrounding {
  priors: SnapType['ecology']['priors'];
  taxa: SnapType['ecology']['taxa'];
}

export interface GeneticsGrounding {
  gcContent: number;
  avgHydrophobicity: number;
  codons: SnapType['genetics']['codons'];
}

export interface GroundingData {
  chemistry: ChemistryGrounding;
  ecology: EcologyGrounding;
  genetics: GeneticsGrounding;
  provenance: SnapType['sources'];
}

const ZERO8 = [0, 0, 0, 0, 0, 0, 0, 0];

function toStoichiometry(s: EngineStoichiometry) {
  return {
    plant: s.plant,
    meat: s.meat,
    aminoAcid: s.aminoAcid,
    fattyAcid: s.fattyAcid,
    sugar: s.sugar,
    glucose: s.glucose,
  };
}

export function parseEnrichment(json: unknown): GroundingData {
  const parsed = EnrichmentSnapshot.parse(json);
  const formulas: Record<number, string> = {};
  const mole_names: string[] = [];
  for (const m of parsed.chemistry.molecules) {
    formulas[m.index] = m.molecularFormula ?? '';
    mole_names[m.index] = m.name;
  }
  return {
    chemistry: {
      ...toStoichiometry(parsed.chemistry.stoichiometry),
      molecularFormulas: formulas,
      mole_names,
    },
    ecology: { priors: parsed.ecology.priors, taxa: parsed.ecology.taxa },
    genetics: {
      gcContent: parsed.genetics.prior.gcContent,
      avgHydrophobicity: parsed.genetics.prior.avgHydrophobicity,
      codons: parsed.genetics.codons,
    },
    provenance: parsed.sources,
  };
}

/** Load the default checked-in snapshot or return null if absent/invalid. */
export function loadEnrichment(path: string = ENRICHMENT_PATH): GroundingData | null {
  try {
    const raw = readFileSync(path, 'utf-8');
    return parseEnrichment(JSON.parse(raw));
  } catch (e: any) {
    return null;
  }
}

/** Load the raw (schema-validated) snapshot object — same shape the engine
 *  receives as `WorldConfig.grounding`. */
export function loadEnrichmentRaw(path: string = ENRICHMENT_PATH): SnapType | null {
  try {
    const raw = readFileSync(path, 'utf-8');
    const parsed = EnrichmentSnapshot.parse(JSON.parse(raw));
    return parsed;
  } catch (e: any) {
    return null;
  }
}

/**
 * Fallback hand-authored stoichiometry — the original engine defaults, used
 * when no enrichment snapshot is present. Keeps ungrounded runs behaviourally
 * identical to the current baseline.
 */
export function defaultStoichiometry() {
  return {
    plant: [6, 4, 3, 1.5, 0, 0, 0, 0],
    meat: [5, 3, 0, 3, 1.5, 1, 0.8, 0],
    aminoAcid: ZERO8,
    fattyAcid: ZERO8,
    sugar: ZERO8,
    glucose: ZERO8,
    molecularFormulas: {},
    mole_names: [] as string[],
  };
}
